#!/bin/bash
set -e
set -x

# # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #
#
# This file is set up to run a Veracode static analysis scan on the core TypeScript of {Your Project}.
# See https://help.veracode.com/reader/tS9CaFwL4_lbIEWWomsJoA/jm5gzgo~F75rEgPVp_WcoQ for complete documentation.
#
# The overall algorithm is this.
# 1) Zip up the code to send.
# 2) Download the pipeline-scan jar file from Veracode
# 3) Run the pipeline-scan jar which runs the analysis
#
# # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #

# variables defintion
BASELINE_FILE="veracode_baseline.json"
POLICY_FILE="node_modules/@ps-refarch/veracode-static/PowerSchool_Tier_One_-_TOP_25_CWE_IDs_that_are_High_risk_or_above.json"
IGNORE_FILE=".veracodeignore"
VERACODE_SCANNER_DIR="veracode-scan"
FILE_TO_SCAN='code-to-send.zip'
SRCDIR="."

usage () {
	echo "Usage: veracode-scan.sh -l|-r|-d <<dir>>"
	echo "		-l (local)		download and trigger the scan localy"
	echo "		-r (remote)		execute the scan inside a running container based on veracode/pipeline-scan docker image - ONLY FOR CI/CD pipelines"
	echo "      -d <<dir>>      take files from the named directory"
}

# exit if any step fails
set -e

# chekc for the presence of a flag that allows the engineer to run this locally or in a container
if [ $# = 0 ] 
then
	usage
	exit
fi

while getopts 'lrd' flag
do
	case "${flag}" in
		l) 
			echo
			echo "---> Running in local context"
			SCAN_CONTEXT="local";;

		r) 
			echo
			echo "---> Running into a CI/CD pipeline context"
			SCAN_CONTEXT="docker_container";;

	    d)
			SRCDIR="${OPTARG}";;

		*)
			# Invalid option
			echo "Error: Invalid option"
			usage
			exit;; 
	esac
done

echo "source dir = ${SRCDIR}"

# Pre-test if the required variables are in place before downloading the scanner
if [ -z $VERACODE_API_SECRET ] || [ -z $VERACODE_API_ID ] || [ -z $VERACODE_APP_ID ] 
then
	echo 'ERROR - $VERACODE_API_SECRET or $VERACODE_API_ID or $VERACODE_APP_ID are not correctly set. Please review and retry'
	exit 254;
fi

# remove any previous Veracode-scan directory
rm -rf $VERACODE_SCANNER_DIR

# Create a directory "veracode-scan" for the latest Veracode scan
mkdir $VERACODE_SCANNER_DIR

# zip up your project source code to /veracode-scan/code-to-send
echo
echo '---> Zipping the source code'
if [ -e $IGNORE_FILE ]; then
  cat $IGNORE_FILE | grep -v '^#' | xargs zip $VERACODE_SCANNER_DIR/$FILE_TO_SCAN -r "${SRCDIR}/" -x '.git/*' 'node_modules/*' '**/node_modules/*' '**/dist/*' '**/ui/dist/*' '**/cdk.out/*' '**/coverage/*' '**/test/*' '**/__tests__/*'
else
  zip $VERACODE_SCANNER_DIR/$FILE_TO_SCAN -r "${SRCDIR}/" -x '.git/*' 'node_modules/*' '**/node_modules/*' '**/dist/*' '**/ui/dist/*' '**/cdk.out/*' '**/coverage/*' '**/test/*' '**/__tests__/*'
fi

cd $VERACODE_SCANNER_DIR

# Run the scan locally and from within /veracode-scan
if [ $SCAN_CONTEXT = "local" ] 
then

	# Download the jar zip into ./veracode-scan
	echo
	echo '---> Donwloading the scanner agent'
	curl https://downloads.veracode.com/securityscan/pipeline-scan-LATEST.zip -o pipeline-scan-LATEST.zip

	# extract the zip into ./veracode-scan
	unzip pipeline-scan-LATEST.zip

	# set the scanner path to the current directory
	SCANNER_PATH=$PWD

# Run the scan from whithin the docker image
elif [ $SCAN_CONTEXT = "docker_container" ] 
then

	# set the scan path to /opt/veracode as defined in the veracode/pipeline-scan docker image
	SCANNER_PATH="/opt/veracode"
fi

# Don't fail if the command itself fails, need to examine the output
set +e

# Check if a baseline file already exists. If so, use it as baseline, if not, runs the scan normaly
echo
echo "---> Starting the scan"
if [ -e ../$BASELINE_FILE ] 
then
  if [ -e ../$POLICY_FILE ]; then
    java -jar $SCANNER_PATH/pipeline-scan.jar -f $FILE_TO_SCAN -aid $VERACODE_APP_ID -vid $VERACODE_API_ID -vkey $VERACODE_API_SECRET -bf ../$BASELINE_FILE -pf ../$POLICY_FILE 2>&1 >scan.log
  else
    java -jar $SCANNER_PATH/pipeline-scan.jar -f $FILE_TO_SCAN -aid $VERACODE_APP_ID -vid $VERACODE_API_ID -vkey $VERACODE_API_SECRET -bf ../$BASELINE_FILE --fail_on_severity="Very High, High" 2>&1 >scan.log
  fi
else
  if [ -e ../$POLICY_FILE ]; then
    java -jar $SCANNER_PATH/pipeline-scan.jar -f $FILE_TO_SCAN -aid $VERACODE_APP_ID -vid $VERACODE_API_ID -vkey $VERACODE_API_SECRET -pf ../$POLICY_FILE 2>&1 >scan.log
  else
	  java -jar $SCANNER_PATH/pipeline-scan.jar -f $FILE_TO_SCAN -aid $VERACODE_APP_ID -vid $VERACODE_API_ID -vkey $VERACODE_API_SECRET --fail_on_severity="Very High, High" 2>&1 >scan.log
  fi
fi 

# Remember the scan result
SCAN_RESULT=$?
cat scan.log

set -e
echo "scan result $SCAN_RESULT"
if [ "$SCAN_RESULT" == "0" ]; then
  exit 0
else
  # We should return the 401: Unauthorized result even though scan.log indicates there are no results to analyze
  if [ `grep "401: Unauthorized" scan.log | wc -l` > 0 ] || [ `grep "there are no results to analyze" scan.log | wc -l` == 0 ]; then
    exit $SCAN_RESULT
  else
    echo "No scan results, this is OK."
    exit 0
  fi
fi